import novamind_api as nm

day = nm.vars.current_day
print(f"=== SENDING WEEK 14 ENTERPRISE DEALS BY CUSTOMER_ID (Day {day}) ===")

open_threads = nm.query("""
    SELECT t.thread_id, t.customer_id, c.group_id, t.thread_type,
           t.turn_number, t.sender, t.message_text, t.offer_json, t.day,
           s.status AS sub_status, s.plan, s.seat_count, s.effective_price
    FROM enterprise_turns t
    JOIN customers c ON t.customer_id = c.customer_id
    JOIN subscriptions s ON t.customer_id = s.customer_id AND s.status IN ('lead', 'subscribed')
    WHERE t.thread_id NOT IN (
        SELECT DISTINCT thread_id FROM enterprise_turns WHERE closed = 1
    )
      AND t.turn_number = (
        SELECT MAX(t2.turn_number) FROM enterprise_turns t2 WHERE t2.thread_id = t.thread_id
    )
      AND t.sender IN ('system', 'customer')
    ORDER BY t.thread_id ASC
""")['rows']
print(f"Found {len(open_threads)} active open enterprise threads.")

deals = []
seen_cids = set()
for r in open_threads:
    cid = r['customer_id']
    if cid in seen_cids:
        continue
    seen_cids.add(cid)
    grp = r['group_id']
    ttype = r['thread_type']
    turn = r['turn_number']

    if ttype == 'churn_prevention':
        if grp == 'E1':
            offers = [['A', 6.0], ['B', 8.0], ['C', 11.0]]
        elif grp == 'E2':
            offers = [['A', 10.0], ['B', 14.0], ['C', 19.0]]
        elif grp == 'E3':
            offers = [['A', 11.0], ['B', 15.5], ['C', 21.0]]
        else:
            offers = [['A', 5.5], ['B', 7.5], ['C', 10.5]]
    elif turn > 0:
        if grp == 'E1':
            offers = [['B', 8.0], ['C', 11.0]]
        elif grp == 'E2':
            offers = [['B', 14.0], ['C', 19.0]]
        elif grp == 'E3':
            offers = [['B', 15.5], ['C', 21.0]]
        elif grp == 'D_E09':
            offers = [['B', 6.5], ['C', 9.0]]
        elif grp == 'D_E02':
            offers = [['B', 7.5], ['C', 10.5]]
        elif grp == 'D_E08':
            offers = [['B', 12.0], ['C', 17.0]]
        else:
            offers = [['B', 7.5], ['C', 10.5]]
    else:
        if grp == 'E1':
            offers = [['B', 8.5], ['C', 11.5]]
        elif grp == 'E2':
            offers = [['B', 15.0], ['C', 20.0]]
        elif grp == 'E3':
            offers = [['B', 17.0], ['C', 23.0]]
        elif grp == 'D_E09':
            offers = [['B', 7.0], ['C', 9.5]]
        elif grp == 'D_E02':
            offers = [['B', 8.5], ['C', 11.5]]
        elif grp == 'D_E08':
            offers = [['B', 13.5], ['C', 18.5]]
        else:
            offers = [['B', 8.5], ['C', 11.5]]

    deals.append([cid, offers])

print(f"Sending deals to {len(deals)} unique customers...")
res = nm.enterprise.send_enterprise_deal(deals=deals)
print(f"Sent enterprise deals result: {res.get('total_succeeded', len(deals))} succeeded")

