    'S1': 4500.0,
    'S2': 4500.0,
    'S3': 2200.0,
}
for g in known_groups:
    if g not in ops_spend and g.startswith('D_'):
        ops_spend[g] = 500.0
nm.analytics.set_targeted_ops_spend(by_group=ops_spend)

# 5. Optimize Ad Spend ($55,000/day across top ROI channels)
ad_spend = {
    'content_marketing': {'S2': 17000.0, 'S1': 10000.0, 'D_S10': 3500.0, 'D_S04': 2500.0},
    'referral_program': {'S3': 10000.0, 'S1': 5500.0, 'D_S07': 4500.0, 'D_S05': 1500.0, 'D_S06': 1500.0},
}
for g in known_groups:
