        elif grp == 'D_E07':
            offers = [['A', 11.0], ['B', 15.0], ['C', 21.0]]
        else:
            offers = [['A', 5.0], ['B', 7.0], ['C', 11.0]]
    elif turn > 0:
        if grp == 'E1':
            offers = [['B', 7.5], ['C', 11.0]]
        elif grp == 'E2':
            offers = [['B', 13.5], ['C', 25.0]]
        elif grp == 'E3':
            offers = [['B', 14.5], ['C', 20.5]]
        elif grp == 'D_E09':
            offers = [['B', 6.5], ['C', 11.0]]
        elif grp == 'D_E02':
            offers = [['B', 6.5], ['C', 11.0]]
        elif grp == 'D_E08':
            offers = [['B', 12.0], ['C', 17.0]]
        elif grp == 'D_E07':
            offers = [['B', 15.5], ['C', 22.0]]
        else:
            offers = [['B', 7.0], ['C', 11.0]]
    else:
        if grp == 'E1':
            offers = [['B', 8.5], ['C', 12.0]]
        elif grp == 'E2':
            offers = [['B', 14.5], ['C', 26.0]]
        elif grp == 'E3':
            offers = [['B', 16.0], ['C', 23.0]]
        elif grp == 'D_E09':
            offers = [['B', 7.5], ['C', 12.0]]
        elif grp == 'D_E02':
            offers = [['B', 7.5], ['C', 12.0]]
        elif grp == 'D_E08':
            offers = [['B', 13.5], ['C', 19.0]]
        elif grp == 'D_E07':
            offers = [['B', 17.5], ['C', 25.0]]
        else:
            offers = [['B', 8.0], ['C', 12.0]]

    deals.append([cid, offers])

print(f"Found {len(deals)} unique customer threads:", counts_by_type)
if deals:
    res = nm.enterprise.send_enterprise_deal(deals=deals)
    print(f"Sent enterprise deals: {res.get('total_succeeded', len(deals))} succeeded")

# 7. Post Social Media Response to Post #344
try:
