import json
import novamind_api as nm

day = nm.vars.current_day
print(f"=== CONFIGURING WEEK {(day // 7) + 1} (Day {day}) ===")

# 1. Check daily usage over the last 7 days and tune Quotas to prevent any overload (>300M/day)
sdays = nm.query(f"SELECT day, total_usage_units, capacity_units, p95_ms FROM service_day WHERE day > {day-7} ORDER BY day")['rows']
for r in sdays:
    print(f"  Day {r['day']}: usage={r['total_usage_units']:,} / {r['capacity_units']:,} (p95={r['p95_ms']:.1f}ms)")

nm.pricing.set_usage_quotas(A=130, B=220, C=260)
print("Set Quotas to A=130, B=220, C=260 to keep weekday peak usage < 300M/day with zero overload")

# 2. Check R&D Projects and start available Tiers 1..10 (while day + mean_days <= 465 and cash >= $3M buffer)
rp = nm.research.list_research_projects()
for t in rp.get('tiers', []):
    print(f"  Tier {t['tier']} ({t['name']}): cost=${t['cost']:,}, in_prog={t['in_progress']}, done={t['completed']}, boost={t['total_quality_boost']}")
    if t['in_progress'] == 0 and (day + t['mean_days'] <= 465):
        cash_now = nm.query("SELECT COALESCE(SUM(amount), 0) AS cash FROM ledger")['rows'][0]['cash']
        if cash_now - t['cost'] >= 3000000:
            try:
                res_r = nm.research.start_research_project(tier=t['tier'])
                print(f"  -> Started Tier {t['tier']}:", res_r)
            except Exception as e:
                print(f"  -> Start Tier {t['tier']} error:", e)

ov = nm.market.get_market_overview()
known_groups = [g['group_id'] if isinstance(g, dict) else g for g in ov.get("known_groups", [])]

# 3. Tailor Individual Retail Prices per Group & Plan via set_promotion(by_group_plan=...)
by_group_plan_promo = {
    'S1':    {'A': 2.0, 'B': 12.0, 'C': 24.0},   # Effective: A=$18, B=$46, C=$94
    'D_S03': {'A': 4.0, 'B': 31.0, 'C': 70.0},   # WTP~$25.5: Effective A=$16, B=$27, C=$48
    'D_S08': {'A': 5.0, 'B': 25.0, 'C': 72.0},   # WTP~$43.6: Effective A=$15, B=$33, C=$46
    'D_S06': {'A': 4.0, 'B': 20.0, 'C': 60.0},   # WTP~$50.9: Effective A=$16, B=$38, C=$58
    'D_S01': {'A': 4.0, 'B': 18.0, 'C': 52.0},   # WTP~$58.2: Effective A=$16, B=$40, C=$66
    'D_S05': {'A': 3.0, 'B': 15.0, 'C': 42.0},   # WTP~$65.5: Effective A=$17, B=$43, C=$76
    'D_S02': {'A': 2.0, 'B': 12.0, 'C': 32.0},   # WTP~$72.7: Effective A=$18, B=$46, C=$86
    'D_S10': {'A': 1.0, 'B':  5.0, 'C': 12.0},   # Effective A=$19, B=$53, C=$106
    'D_S09': {'A': 1.0, 'B':  5.0, 'C': 10.0},   # WTP~$109: Effective A=$19, B=$53, C=$108
    'D_S04': {'A': 1.0, 'B':  4.0, 'C':  6.0},   # WTP~$116: Effective A=$19, B=$54, C=$112
    'D_S07': {'A': 1.0, 'B':  3.0, 'C':  0.0},   # High WTP: Effective A=$19, B=$55, C=$118
    'S2':    {'A': 1.0, 'B':  3.0, 'C':  0.0},   # High WTP: Effective A=$19, B=$55, C=$118
    'S3':    {'A': 1.0, 'B':  3.0, 'C':  0.0},   # High WTP: Effective A=$19, B=$55, C=$118
}
nm.pricing.set_promotion(global_promotion=0.0, by_group={}, by_group_plan=by_group_plan_promo)
nm.marketing.set_lead_promotion(global_promotion=2.0)

# 4. Scale Global & Targeted Dev Spend and Ops Spend (with end-game cash taper after Day 460)
if day >= 465:
    nm.marketing.set_daily_spend(operations=45000.0, development=0.0)
    dev_spend = {g: 0.0 for g in known_groups}
elif day >= 435:
    nm.marketing.set_daily_spend(operations=55000.0, development=10000.0)
    dev_spend = {g: 8000.0 for g in known_groups}
else:
    nm.marketing.set_daily_spend(operations=60000.0, development=25000.0)
    dev_spend = {g: 18000.0 for g in known_groups}
nm.analytics.set_targeted_dev_spend(targeted_spend=dev_spend)

ops_spend = {
    'E1': 6500.0,
    'E2': 5000.0,
    'E3': 3000.0,
    'D_E01': 3500.0,
    'D_E02': 4000.0,
    'D_E03': 3500.0,
    'D_E04': 3500.0,
    'D_E05': 4000.0,
    'D_E06': 3000.0,
    'D_E07': 4000.0,
    'D_E08': 3000.0,
    'D_E09': 2000.0,
    'D_E10': 3000.0,
    'D_S01': 4500.0,
    'D_S02': 5000.0,
    'D_S03': 4000.0,
    'D_S04': 5500.0,
    'D_S05': 3500.0,
    'D_S06': 4000.0,
    'D_S07': 5500.0,
    'D_S08': 3500.0,
    'D_S09': 5000.0,
    'D_S10': 5000.0,
    'S1': 22000.0,
    'S2': 10000.0,
    'S3': 6000.0,
}
nm.analytics.set_targeted_ops_spend(by_group=ops_spend)

# 5. Precision Ad Spend ($20,000/day focused ONLY on $108-$118/mo Plan C groups to save $1.12M/wk & avoid overload)
if day >= 465:
    ad_spend = {'content_marketing': {}, 'referral_program': {}}
else:
    ad_spend = {
        'content_marketing': {
            'D_S04': 4000.0,
            'D_S09': 3000.0,
            'S2': 3000.0,
            'D_S10': 2000.0,
        },
        'referral_program': {
            'D_S07': 4000.0,
            'S3': 2000.0,
            'D_S02': 2000.0,
        },
    }
nm.marketing.set_targeted_ad_spend(targeted_spend=ad_spend)

# 6. Handle Enterprise Threads
open_threads = nm.query("""
    SELECT t.thread_id, t.customer_id, c.group_id, t.thread_type,
           t.turn_number, t.sender, t.day, t.offer_json, t.message_text,
           s.status AS sub_status, s.plan, s.seat_count, s.effective_price
    FROM enterprise_turns t
    JOIN customers c ON t.customer_id = c.customer_id
    JOIN subscriptions s ON t.customer_id = s.customer_id AND s.status IN ('lead', 'subscribed')
    WHERE t.thread_id NOT IN (
        SELECT DISTINCT thread_id FROM enterprise_turns WHERE closed = 1
    )
      AND t.turn_number = (
        SELECT MAX(t2.turn_number) FROM enterprise_turns t2 WHERE t2.thread_id = t.thread_id
    )
      AND t.sender IN ('system', 'customer')
    ORDER BY t.thread_id ASC
""")['rows']

deals = []
reneg_rejections = []
seen_cids = set()
counts_by_type = {}

for r in open_threads:
    cid = r['customer_id']
    if cid in seen_cids:
        continue
    seen_cids.add(cid)
    grp = r['group_id']
    ttype = r['thread_type']
    turn = r['turn_number']
    counts_by_type[(grp, ttype, turn)] = counts_by_type.get((grp, ttype, turn), 0) + 1

    if ttype == 'renegotiation':
        # Close open seller-initiated renegotiation threads cleanly while preserving existing contracts
        reneg_rejections.append({"customer_id": cid})
        continue

    # Check if customer provided an explicit counter-offer price in offer_json on turn >= 2
    cust_p = None
    if turn >= 2 and r.get('offer_json') and r['offer_json'] != '{}':
        try:
            cust_p = float(json.loads(r['offer_json']).get('price', 0))
        except Exception:
            cust_p = None

    if ttype == 'churn_prevention':
        if grp == 'E1':
            offers = [['A', 6.5], ['B', 9.5], ['C', 13.0]]
        elif grp == 'E2':
            offers = [['A', 11.0], ['B', 16.5], ['C', 27.5]]
        elif grp == 'E3':
            offers = [['A', 11.5], ['B', 17.0], ['C', 24.5]]
