import json
import novamind_api as nm

day = nm.vars.current_day
print(f"=== CONFIGURING WEEK {(day // 7) + 1} (Day {day}) ===")

# 1. Upgrade Model Tiers to A=2 (0.75x), B=3 (0.90x), C=4 (1.00x) to add +2.70 quality points to Plan C and +4.0 to Plan B!
nm.pricing.set_model_tiers(A=2, B=3, C=4)
print("Upgraded Model Tiers to A=2 (0.75x), B=3 (0.90x), C=4 (1.00x)")

sdays = nm.query(f"SELECT day, total_usage_units, capacity_units, p95_ms FROM service_day WHERE day > {day-7} ORDER BY day")['rows']
for r in sdays:
    print(f"  Day {r['day']}: usage={r['total_usage_units']:,} / {r['capacity_units']:,} (p95={r['p95_ms']:.1f}ms)")

nm.pricing.set_usage_quotas(A=125, B=205, C=245)
print("Set Quotas to A=125, B=205, C=245 to balance Tier 4 compute cost with high quality cushion")

# 2. Start fast R&D Tiers 1..4 while day + mean_days <= 465
rp = nm.research.list_research_projects()
for t in rp.get('tiers', []):
    print(f"  Tier {t['tier']} ({t['name']}): cost=${t['cost']:,}, in_prog={t['in_progress']}, done={t['completed']}, boost={t['total_quality_boost']}")
    if t['in_progress'] == 0 and t['tier'] <= 4 and (day + t['mean_days'] <= 465):
        try:
            res_r = nm.research.start_research_project(tier=t['tier'])
            print(f"  -> Started Tier {t['tier']}:", res_r)
        except Exception as e:
            print(f"  -> Start Tier {t['tier']} error:", e)

ov = nm.market.get_market_overview()
known_groups = [g['group_id'] if isinstance(g, dict) else g for g in ov.get("known_groups", [])]

# 3. Tailor Individual Retail Prices per Group & Plan (with Plan B=T3 0.90x and Plan C=T4 1.00x!)
nm.pricing.set_prices(A=20.0, B=58.0, C=118.0)
by_group_plan_promo = {
    'S1':    {'A':  6.0, 'B': 24.0, 'C': 56.0},   # Effective: A=$14, B=$34 (T3), C=$62 (T4)
    'D_S03': {'A':  6.0, 'B': 28.0, 'C': 68.0},   # Effective: A=$14, B=$30 (T3), C=$50 (T4)
    'D_S08': {'A':  8.0, 'B': 32.0, 'C': 76.0},   # Effective: A=$12, B=$26 (T3), C=$42 (T4)
    'D_S06': {'A':  7.0, 'B': 30.0, 'C': 72.0},   # Effective: A=$13, B=$28 (T3), C=$46 (T4)
    'D_S01': {'A':  6.0, 'B': 26.0, 'C': 66.0},   # Effective: A=$14, B=$32 (T3), C=$52 (T4)
    'D_S05': {'A':  6.0, 'B': 26.0, 'C': 66.0},   # Effective: A=$14, B=$32 (T3), C=$52 (T4)
    'D_S02': {'A':  4.0, 'B': 18.0, 'C': 40.0},   # Effective: A=$16, B=$40 (T3), C=$78 (T4)
    'D_S10': {'A':  3.0, 'B': 12.0, 'C': 22.0},   # Effective: A=$17, B=$46 (T3), C=$96 (T4)
    'D_S09': {'A':  3.0, 'B': 14.0, 'C': 28.0},   # Effective: A=$17, B=$44 (T3), C=$90 (T4)
    'D_S04': {'A':  5.0, 'B': 22.0, 'C': 54.0},   # Effective: A=$15, B=$36 (T3), C=$64 (T4)
    'D_S07': {'A':  4.0, 'B': 18.0, 'C': 42.0},   # Effective: A=$16, B=$40 (T3), C=$76 (T4)
    'S2':    {'A':  3.0, 'B': 12.0, 'C': 20.0},   # Effective: A=$17, B=$46 (T3), C=$98 (T4)
    'S3':    {'A':  5.0, 'B': 20.0, 'C': 52.0},   # Effective: A=$15, B=$38 (T3), C=$66 (T4)
}
nm.pricing.set_promotion(global_promotion=0.0, by_group={}, by_group_plan=by_group_plan_promo)
nm.marketing.set_lead_promotion(global_promotion=3.0)

# 4. Strong Dev & Ops Spend to prevent outages and keep quality ahead of competitors (taper after Day 470)
core_groups = {
    'S2', 'D_S02', 'D_S09', 'D_S10', 'D_S03', 'S1', 'D_S07', 'D_S01', 'S3',
    'E2', 'D_E07', 'D_E02', 'E3', 'D_E04', 'D_E08', 'D_E05', 'D_E01', 'D_E03', 'D_E10', 'D_E06', 'E1'
}
if day >= 472:
    nm.marketing.set_daily_spend(operations=55000.0, development=0.0)
    dev_spend = {g: 0.0 for g in known_groups}
elif day >= 455:
    nm.marketing.set_daily_spend(operations=70000.0, development=10000.0)
    dev_spend = {g: (8000.0 if g in core_groups else 0.0) for g in known_groups}
else:
    nm.marketing.set_daily_spend(operations=85000.0, development=20000.0)
    dev_spend = {g: (16000.0 if g in core_groups else 4000.0) for g in known_groups}
nm.analytics.set_targeted_dev_spend(targeted_spend=dev_spend)

ops_spend = {
    'E1': 2000.0,
    'E2': 5000.0,
    'E3': 3000.0,
    'D_E01': 3000.0,
    'D_E02': 4000.0,
    'D_E03': 3000.0,
    'D_E04': 3500.0,
    'D_E05': 3500.0,
    'D_E06': 1500.0,
    'D_E07': 4000.0,
    'D_E08': 3000.0,
    'D_E09': 500.0,
    'D_E10': 1500.0,
    'D_S01': 2500.0,
    'D_S02': 7000.0,
    'D_S03': 3500.0,
    'D_S04': 1500.0,
    'D_S05': 1000.0,
    'D_S06': 1000.0,
    'D_S07': 5000.0,
    'D_S08': 1000.0,
    'D_S09': 5500.0,
    'D_S10': 4500.0,
    'S1': 15000.0,
    'S2': 14000.0,
    'S3': 2500.0,
}
nm.analytics.set_targeted_ops_spend(by_group=ops_spend)

# 5. Precision Ad Spend ($25,000/day on highest-margin Plan C groups, $0 after Day 460)
if day >= 460:
    ad_spend = {'content_marketing': {}, 'referral_program': {}}
else:
    ad_spend = {
        'content_marketing': {
            'S2': 8000.0,
            'D_S10': 5000.0,
            'D_S09': 4000.0,
        },
        'referral_program': {
            'D_S02': 5000.0,
            'D_S07': 3000.0,
        },
    }
nm.marketing.set_targeted_ad_spend(targeted_spend=ad_spend)

# 6. Handle Enterprise Threads (Now with Plan B on T3=0.90x and Plan C on T4=1.00x!)
open_threads = nm.query("""
    SELECT t.thread_id, t.customer_id, c.group_id, t.thread_type,
           t.turn_number, t.sender, t.day, t.offer_json, t.message_text,
           s.status AS sub_status, s.plan, s.seat_count, s.effective_price
    FROM enterprise_turns t
    JOIN customers c ON t.customer_id = c.customer_id
    JOIN subscriptions s ON t.customer_id = s.customer_id AND s.status IN ('lead', 'subscribed')
    WHERE t.thread_id NOT IN (
        SELECT DISTINCT thread_id FROM enterprise_turns WHERE closed = 1
    )
      AND t.turn_number = (
        SELECT MAX(t2.turn_number) FROM enterprise_turns t2 WHERE t2.thread_id = t.thread_id
    )
      AND t.sender IN ('system', 'customer')
    ORDER BY t.thread_id ASC
""")['rows']

deals = []
reneg_rejections = []
