import json
import novamind_api as nm

day = nm.vars.current_day
print(f"=== CONFIGURING WEEK {(day // 7) + 1} (Day {day}) ===")

# 1. Maintain Model Tiers A=2, B=3, C=4 so Plan C delivered quality is 26.8-29.5+ (1.00x multiplier)
nm.pricing.set_model_tiers(A=2, B=3, C=4)
print("Set Model Tiers to A=2 (0.75x), B=3 (0.90x), C=4 (1.00x) for maximum renewal and churn_prevention acceptance")

sdays = nm.query(f"SELECT day, total_usage_units, capacity_units, p95_ms FROM service_day WHERE day > {day-7} ORDER BY day")['rows']
for r in sdays:
    print(f"  Day {r['day']}: usage={r['total_usage_units']:,} / {r['capacity_units']:,} (p95={r['p95_ms']:.1f}ms)")

nm.pricing.set_usage_quotas(A=140, B=235, C=275)
print("Set Quotas to A=140, B=235, C=275 for high retention and controlled compute cost")

# 2. Freeze ALL new R&D Capex for final 45 days (Days 455-500); 4 in-progress projects will complete for free!
rp = nm.research.list_research_projects()
for t in rp.get('tiers', []):
    print(f"  Tier {t['tier']} ({t['name']}): cost=${t['cost']:,}, in_prog={t['in_progress']}, done={t['completed']}, boost={t['total_quality_boost']}")

ov = nm.market.get_market_overview()
known_groups = [g['group_id'] if isinstance(g, dict) else g for g in ov.get("known_groups", [])]

# 3. Tailor Individual Retail Prices per Group & Plan for Model Tier 4 (1.00x = 26.8-29.5+ quality)
nm.pricing.set_prices(A=20.0, B=58.0, C=118.0)
by_group_plan_promo = {
    'S1':    {'A': 10.0, 'B': 32.0, 'C': 58.0},   # Effective: A=$10, B=$26, C=$60
    'D_S03': {'A':  8.0, 'B': 28.0, 'C': 70.0},   # Effective: A=$12, B=$30, C=$48
    'D_S08': {'A': 11.0, 'B': 42.0, 'C': 88.0},   # Effective: A=$9,  B=$16, C=$30
    'D_S06': {'A': 10.0, 'B': 38.0, 'C': 82.0},   # Effective: A=$10, B=$20, C=$36
    'D_S01': {'A':  9.0, 'B': 35.0, 'C': 76.0},   # Effective: A=$11, B=$23, C=$42
    'D_S05': {'A':  9.0, 'B': 35.0, 'C': 76.0},   # Effective: A=$11, B=$23, C=$42
    'D_S02': {'A':  4.0, 'B': 20.0, 'C': 42.0},   # Effective: A=$16, B=$38, C=$76
    'D_S10': {'A':  3.0, 'B': 12.0, 'C': 24.0},   # Effective: A=$17, B=$46, C=$94
    'D_S09': {'A':  3.0, 'B': 14.0, 'C': 30.0},   # Effective: A=$17, B=$44, C=$88
    'D_S04': {'A':  8.0, 'B': 32.0, 'C': 68.0},   # Effective: A=$12, B=$26, C=$50
    'D_S07': {'A':  6.0, 'B': 24.0, 'C': 44.0},   # Effective: A=$14, B=$34, C=$74
    'S2':    {'A':  3.0, 'B': 12.0, 'C': 22.0},   # Effective: A=$17, B=$46, C=$96
    'S3':    {'A':  8.0, 'B': 30.0, 'C': 64.0},   # Effective: A=$12, B=$28, C=$54
}
nm.pricing.set_promotion(global_promotion=0.0, by_group={}, by_group_plan=by_group_plan_promo)
nm.marketing.set_lead_promotion(global_promotion=3.0)

# 4. End-Game Taper for Ops & Dev Spend (saving +$1.3M/week while keeping Open Issues low)
core_groups = {
    'S2', 'D_S02', 'D_S09', 'D_S10', 'D_S03', 'S1', 'D_S07',
    'E2', 'D_E07', 'D_E02', 'E3', 'D_E04', 'D_E08', 'D_E05', 'D_E01', 'D_E03', 'D_E10'
}
if day >= 490:
    nm.marketing.set_daily_spend(operations=15000.0, development=0.0)
    dev_spend = {g: 0.0 for g in known_groups}
    ops_scale = 0.0
elif day >= 476:
    nm.marketing.set_daily_spend(operations=45000.0, development=0.0)
    dev_spend = {g: 0.0 for g in known_groups}
    ops_scale = 0.4
elif day >= 469:
    nm.marketing.set_daily_spend(operations=60000.0, development=0.0)
    dev_spend = {g: 0.0 for g in known_groups}
    ops_scale = 0.7
else:
    nm.marketing.set_daily_spend(operations=70000.0, development=20000.0)
    dev_spend = {g: (1500.0 if g in core_groups else 0.0) for g in known_groups}
    ops_scale = 1.0
nm.analytics.set_targeted_dev_spend(targeted_spend=dev_spend)

base_ops_spend = {
    'E1': 500.0,
    'E2': 3000.0,
    'E3': 1500.0,
    'D_E01': 1500.0,
    'D_E02': 2000.0,
    'D_E03': 1500.0,
    'D_E04': 1500.0,
    'D_E05': 1500.0,
    'D_E06': 0.0,
    'D_E07': 2000.0,
    'D_E08': 1000.0,
    'D_E09': 0.0,
    'D_E10': 1000.0,
    'D_S01': 0.0,
    'D_S02': 7000.0,
    'D_S03': 2000.0,
    'D_S04': 0.0,
    'D_S05': 0.0,
    'D_S06': 0.0,
    'D_S07': 1500.0,
    'D_S08': 0.0,
    'D_S09': 4000.0,
    'D_S10': 3500.0,
    'S1': 1000.0,
    'S2': 9000.0,
    'S3': 0.0,
}
ops_spend = {g: round(v * ops_scale, 1) for g, v in base_ops_spend.items()}
nm.analytics.set_targeted_ops_spend(by_group=ops_spend)

# 5. High-ROI Targeted Ad Spend on S2, D_S10, D_S09, D_S02 while new subscribers still get 2 billing cycles (Days 455-468)
if day >= 483:
    ad_spend = {'content_marketing': {}, 'referral_program': {}}
elif day >= 469:
    ad_spend = {
        'content_marketing': {
            'S2': 3000.0,
            'D_S10': 1500.0,
            'D_S09': 1000.0,
        },
        'referral_program': {
            'D_S02': 1500.0,
        },
    }
else:
    ad_spend = {
        'content_marketing': {
            'S2': 8000.0,
            'D_S10': 4500.0,
            'D_S09': 3000.0,
        },
        'referral_program': {
            'D_S02': 4500.0,
        },
    }
nm.marketing.set_targeted_ad_spend(targeted_spend=ad_spend)

# 6. Handle Enterprise Threads
open_threads = nm.query("""
    SELECT t.thread_id, t.customer_id, c.group_id, t.thread_type,
           t.turn_number, t.sender, t.day, t.offer_json, t.message_text,
           s.status AS sub_status, s.plan, s.seat_count, s.effective_price
    FROM enterprise_turns t
    JOIN customers c ON t.customer_id = c.customer_id
    JOIN subscriptions s ON t.customer_id = s.customer_id AND s.status IN ('lead', 'subscribed')
    WHERE t.thread_id NOT IN (
        SELECT DISTINCT thread_id FROM enterprise_turns WHERE closed = 1
    )
      AND t.turn_number = (
        SELECT MAX(t2.turn_number) FROM enterprise_turns t2 WHERE t2.thread_id = t.thread_id
    )
      AND t.sender IN ('system', 'customer')
    ORDER BY t.thread_id ASC
""")['rows']

deals = []
reneg_rejections = []
seen_cids = set()
counts_by_type = {}

for r in open_threads:
    cid = r['customer_id']
    if cid in seen_cids:
        continue
    seen_cids.add(cid)
    grp = r['group_id']
    ttype = r['thread_type']
    turn = r['turn_number']
    cur_price = float(r['effective_price'] or 0.0)
    counts_by_type[(grp, ttype, turn)] = counts_by_type.get((grp, ttype, turn), 0) + 1

    if ttype == 'renegotiation':
        reneg_rejections.append({"customer_id": cid})
        continue

    cust_p = None
    if turn >= 2 and r.get('offer_json') and r['offer_json'] != '{}':
        try:
            cust_p = float(json.loads(r['offer_json']).get('price', 0))
        except Exception:
            cust_p = None

    if ttype == 'churn_prevention':
        if grp == 'E1':
            c_cap, a_p, b_p = 8.8, 3.2, 5.0
        elif grp == 'E2':
            c_cap, a_p, b_p = 21.5, 9.0, 14.5
        elif grp == 'E3':
            c_cap, a_p, b_p = 20.5, 9.0, 14.0
        elif grp == 'D_E09':
            c_cap, a_p, b_p = 8.5, 3.0, 4.8
        elif grp == 'D_E02':
            c_cap, a_p, b_p = 11.5, 5.0, 8.0
        elif grp == 'D_E08':
            c_cap, a_p, b_p = 16.5, 7.0, 11.0
        elif grp == 'D_E07':
            c_cap, a_p, b_p = 35.0, 12.0, 18.0
        elif grp == 'D_E03':
            c_cap, a_p, b_p = 20.5, 9.0, 14.0
        elif grp == 'D_E04':
            c_cap, a_p, b_p = 20.5, 8.5, 13.5
        elif grp == 'D_E01':
            c_cap, a_p, b_p = 18.5, 7.5, 12.0
        elif grp == 'D_E05':
            c_cap, a_p, b_p = 15.5, 6.5, 10.5
        elif grp == 'D_E06':
            c_cap, a_p, b_p = 9.5, 4.5, 6.8
        elif grp == 'D_E10':
            c_cap, a_p, b_p = 17.5, 7.0, 11.0
        else:
            c_cap, a_p, b_p = 15.0, 6.0, 9.5

        if cur_price > 1.0:
            c_offer = round(max(8.5, min(c_cap, cur_price * 0.92)), 1)
        else:
            c_offer = c_cap
        offers = [['A', a_p], ['B', b_p], ['C', c_offer]]

        if cust_p is not None and cust_p >= 2.0:
            offers = [
                ['A', round(max(2.5, min(offers[0][1], cust_p * 0.70)), 1)],
                ['B', round(max(4.5, min(offers[1][1], cust_p * 0.90)), 1)],
                ['C', round(max(8.5, min(offers[2][1], cust_p * 1.0)), 1)],
            ]
    elif turn > 0:
        if grp == 'E1':
            offers = [['A', 3.2], ['B', 5.0], ['C', 8.5]]
        elif grp == 'E2':
            offers = [['A', 8.5], ['B', 13.5], ['C', 20.5]]
        elif grp == 'E3':
            offers = [['A', 8.5], ['B', 13.0], ['C', 19.5]]
        elif grp == 'D_E09':
            offers = [['A', 3.0], ['B', 4.8], ['C', 8.5]]
        elif grp == 'D_E02':
            offers = [['A', 4.5], ['B', 7.5], ['C', 11.0]]
        elif grp == 'D_E08':
            offers = [['A', 6.5], ['B', 10.5], ['C', 15.5]]
        elif grp == 'D_E07':
            offers = [['A', 11.5], ['B', 17.5], ['C', 32.0]]
        elif grp == 'D_E03':
            offers = [['A', 8.5], ['B', 13.5], ['C', 19.5]]
        elif grp == 'D_E04':
            offers = [['A', 8.0], ['B', 12.5], ['C', 19.5]]
        elif grp == 'D_E01':
            offers = [['A', 7.0], ['B', 11.0], ['C', 17.5]]
        elif grp == 'D_E05':
            offers = [['A', 6.0], ['B', 9.5], ['C', 14.5]]
        elif grp == 'D_E06':
            offers = [['A', 4.2], ['B', 6.5], ['C', 9.0]]
        elif grp == 'D_E10':
            offers = [['A', 6.5], ['B', 10.0], ['C', 16.0]]
        else:
            offers = [['A', 6.0], ['B', 9.0], ['C', 14.5]]

        if cust_p is not None and cust_p >= 2.0:
            offers = [
                ['A', round(max(2.5, min(offers[0][1], cust_p * 0.70)), 1)],
                ['B', round(max(4.5, min(offers[1][1], cust_p * 0.90)), 1)],
                ['C', round(max(8.5, min(offers[2][1], cust_p * 1.0)), 1)],
            ]
    else:
