            offers = [['B', 14.5], ['C', 21.5]]
        elif grp == 'E3':
            offers = [['B', 14.0], ['C', 20.5]]
        elif grp == 'D_E09':
            offers = [['A', 3.2], ['B', 5.0], ['C', 8.8]]
        elif grp == 'D_E02':
            offers = [['A', 5.0], ['B', 8.0], ['C', 11.5]]
        elif grp == 'D_E08':
            offers = [['B', 11.0], ['C', 16.5]]
        elif grp == 'D_E07':
            offers = [['B', 18.0], ['C', 34.0]]
        elif grp == 'D_E03':
            offers = [['B', 14.0], ['C', 20.5]]
        elif grp == 'D_E04':
            offers = [['B', 13.5], ['C', 20.5]]
        elif grp == 'D_E01':
            offers = [['B', 12.0], ['C', 18.5]]
        elif grp == 'D_E05':
            offers = [['B', 10.5], ['C', 15.5]]
        elif grp == 'D_E06':
            offers = [['A', 4.5], ['B', 6.8], ['C', 9.5]]
        elif grp == 'D_E10':
            offers = [['B', 11.0], ['C', 17.5]]
        else:
            offers = [['B', 10.0], ['C', 15.5]]

    deals.append([cid, offers])

print(f"Found {len(deals)} deal replies and {len(reneg_rejections)} renegotiation rejections:", counts_by_type)

